/* this code is generated by Claude, with this prompt : 
You are a Java developer. 
Generate a Java class called CitySearch for a mobile app called YOLO — a platform for Erasmus students to discover local spots in their city. 
The class should: 1) Store a list of spots with name, category, and city. 2) Allow searching spots by city name (case-insensitive). 3) Allow filtering results by category (e.g. cafe, park, bar). 4) Return the matching results as a list. Include a main method with example data to test it.
*/

import java.util.ArrayList;
import java.util.List;
import java.util.stream.Collectors;

// Represents a single spot in the YOLO app
class Spot {
    private String name;
    private String category;
    private String city;
    private boolean budgetFriendly;
    private boolean freeEntry;
    private String tag;

    public Spot(String name, String category, String city, boolean budgetFriendly, boolean freeEntry, String tag) {
        this.name = name;
        this.category = category;
        this.city = city;
        this.budgetFriendly = budgetFriendly;
        this.freeEntry = freeEntry;
        this.tag = tag;
    }

    public String getName() { return name; }
    public String getCategory() { return category; }
    public String getCity() { return city; }
    public boolean isBudgetFriendly() { return budgetFriendly; }
    public boolean isFreeEntry() { return freeEntry; }
    public String getTag() { return tag; }

    @Override
    public String toString() {
        return String.format("[%s] %s — %s | Budget: %s | Free: %s | Tag: %s",
                city, name, category,
                budgetFriendly ? "Yes" : "No",
                freeEntry ? "Yes" : "No",
                tag);
    }
}

// Handles city-based search and filtering logic
class CitySearch {

    private List<Spot> spots;

    public CitySearch() {
        this.spots = new ArrayList<>();
    }

    public void addSpot(Spot spot) {
        spots.add(spot);
    }

    // Search spots by city name (case-insensitive)
    public List<Spot> searchByCity(String city) {
        return spots.stream()
                .filter(s -> s.getCity().equalsIgnoreCase(city))
                .collect(Collectors.toList());
    }

    // Filter results by category (case-insensitive)
    public List<Spot> filterByCategory(String city, String category) {
        return searchByCity(city).stream()
                .filter(s -> s.getCategory().equalsIgnoreCase(category))
                .collect(Collectors.toList());
    }

    // Filter results by budget-friendly tag
    public List<Spot> filterBudgetFriendly(String city) {
        return searchByCity(city).stream()
                .filter(Spot::isBudgetFriendly)
                .collect(Collectors.toList());
    }

    // Filter results by free entry
    public List<Spot> filterFreeEntry(String city) {
        return searchByCity(city).stream()
                .filter(Spot::isFreeEntry)
                .collect(Collectors.toList());
    }

    // Main method with example data
    public static void main(String[] args) {

        CitySearch search = new CitySearch();

        // Sample data — based on YOLO app UI
        search.addSpot(new Spot("Palmengarten", "park", "Frankfurt", true, true, "Free with Student ID"));
        search.addSpot(new Spot("The Tiny Cup", "cafe", "Frankfurt", true, false, "Student Discount"));
        search.addSpot(new Spot("Mainka Café & Bistro", "cafe", "Frankfurt", false, false, "Local Favourite"));
        search.addSpot(new Spot("Main Tower Rooftop", "bar", "Frankfurt", false, false, "Rooftop View"));
        search.addSpot(new Spot("Kleinmarkthalle", "market", "Frankfurt", true, true, "Budget Friendly"));
        search.addSpot(new Spot("Schlossgarten", "park", "Stuttgart", true, true, "Free Entry"));
        search.addSpot(new Spot("Porsche Museum", "museum", "Stuttgart", false, false, "Must See"));
        search.addSpot(new Spot("Kaffee Mitte", "cafe", "Heilbronn", true, false, "Student Discount"));
        search.addSpot(new Spot("Museum Island", "museum", "Heilbronn", true, true, "Free on Sundays"));

        // Test 1: Search all spots in Frankfurt
        System.out.println("=== All spots in Frankfurt ===");
        search.searchByCity("Frankfurt").forEach(System.out::println);

        // Test 2: Filter cafes in Frankfurt
        System.out.println("\n=== Cafes in Frankfurt ===");
        search.filterByCategory("Frankfurt", "cafe").forEach(System.out::println);

        // Test 3: Budget-friendly spots in Frankfurt
        System.out.println("\n=== Budget-friendly spots in Frankfurt ===");
        search.filterBudgetFriendly("Frankfurt").forEach(System.out::println);

        // Test 4: Free entry spots in Frankfurt
        System.out.println("\n=== Free entry spots in Frankfurt ===");
        search.filterFreeEntry("Frankfurt").forEach(System.out::println);

        // Test 5: All spots in Heilbronn
        System.out.println("\n=== All spots in Heilbronn ===");
        search.searchByCity("Heilbronn").forEach(System.out::println);
    }
}